            "swapping_pxa_to_pxs_is_instant_the": "Convertire PXA in PXS è istantaneo: metà dei PXA viene convertita subito, al netto di una commissione del 5%, mentre l’altra metà resta vincolata come garanzia e torna dopo ~3,5 giorni, adeguata al prezzo di quel momento. Convertire PXS in PXA non ha commissioni e si regola dopo ~3,5 giorni, al prezzo mediano dei witness in quel momento.",
