            "strong_strong_can_transfer_pixa_power_directly": "<strong>@{{username}}</strong> può trasferire Pixa Power direttamente a un altro account, saltando il consueto ciclo di power down di 13 settimane. Questa tesoreria è un account multifirma, quindi nessun singolo accesso può muoverne i fondi — usa <strong>Trasferimento multiplo</strong> qui sotto, dove ogni titolare di chiave firma separatamente lo stesso lotto prima che venga unito e trasmesso.",
