            "total_gain_taxable": "Guadagno totale {{fmtFiat}} {{fiat}} · imponibile {{fmtFiat_2}} {{fiat_2}} {{fmtFiat_3}} {{fmtFiat_4}} {{fmtFiat_5}}",
            "not_taxable_disposals_or_income_proposal_fees": "Non sono cessioni imponibili né redditi. Le commissioni sulle proposte escono dall’account e riducono le tue giacenze; i prelievi dal risparmio conclusi e i power up sono movimenti interni, mostrati per completezza.",
            "seen_in_history_but_not_booked_into": "Presenti nella cronologia ma non contabilizzati nei dati sopra ({{skippedTotal}} operazioni) — azioni sociali o di governance senza impatto sul saldo, redditi già conteggiati al momento della riscossione, o movimenti regolati con un’esecuzione successiva:",
            "reconstructed_from_classified_events": "Ricostruito da {{ingest}} eventi classificati.{{text}}{{fiat}}{{text_2}}{{note}}",
            "deductions_optional_losses_you_carried_forward_f": "Detrazioni — facoltative. Le perdite riportate dagli anni precedenti compensano i guadagni di quest’anno; la cifra della franchigia annuale indica quanta parte della franchigia del tuo Paese hai già usato altrove. Applicate automaticamente dove la tua giurisdizione le prevede.",
            "send_labels_are_assigned_in_the_classify": "Le etichette degli invii vengono assegnate nel passaggio Classifica e memorizzate per account. Se preferisci, modificale in blocco in un foglio di calcolo:",
            "say_what_each_outbound_send_was_so": "Indica cosa era ogni invio in uscita, così viene tassato correttamente. Ogni invio è trattato come una vendita imponibile finché non lo etichetti — contrassegnarlo come tuo exchange, tuoi portafogli, regalo o donazione cambia la tassazione. Le etichette vengono ricordate la volta successiva. Continua le applica e ricalcola il report.",
            "nothing_to_classify_no_outbound_transfers_to": "Nulla da classificare — nella tua cronologia non risultano trasferimenti in uscita verso terzi. Prosegui per rivedere ed esportare.",
            "opening_balances_are_tokens_you_already_held": "I saldi iniziali sono token che possedevi già prima della prima operazione registrata di questo account. Impostali affinché le cessioni più vecchie abbiano un costo reale invece di un guadagno a costo zero (sovrastimato). Il costo è il totale che hai pagato per quell’importo iniziale, in {{cur}}.",
            "generate_a_record_of_your_on_chain": "Genera un resoconto della tua attività on-chain in un intervallo di date, classificato ai fini fiscali dal motore FairFlow. Compila le opzioni, classifica i tuoi invii, poi esporta in PDF, CSV o JSON.",
            "values_use_the_wallets_current_price_a": "I valori usano il prezzo {{fiat}} corrente del portafoglio — una singola istantanea, senza serie storica. Il totale delle giacenze è quindi esatto, ma i guadagni realizzati sono approssimativi (ricavo e costo di una cessione condividono lo stesso prezzo corrente). Collega un oracolo storico o una fonte Kursliste per guadagni esatti.",
            "fiat_values_come_from_the_engines_pxs": "I valori in valuta fiat provengono dal fornitore di prezzi dimostrativo con riferimento a PXS del motore ({{priceDataVersion}}) — collega un oracolo reale o una fonte Kursliste prima di fare affidamento sui dati.",
            "prefilled_from_the_chain_1_vest_pxa": "Precompilato dalla blockchain: 1 VEST = {{_vestingRateAuto}} PXA, quindi 1.000.000 VESTS = {{_vestingRateAuto_2}} PXP. VESTS × questo valore = PXP, e 1 PXP vale quanto 1 PXA. Modifica solo per sovrascrivere.",
