            "it_is_earned_through_protocol_emission_not": "Si guadagna attraverso l’emissione del protocollo; nessuna azienda lo emette o lo vende. Detenerlo non è capitale, non è un deposito e non è una promessa di profitto; non conferisce alcun diritto sui ricavi o sugli attivi di alcun soggetto. Non è pubblicizzato come token di pagamento. Poiché il PXA è semplicemente il PXP nella sua fase liquida, vale lo stesso ragionamento FINMA sul token di utilità che copre il PXP (Nutzungs-Token, 27 marzo 2025, rif. G01518211) — si veda la scheda PXP per il fascicolo completo.",
