            "pixa_is_one_living_being_and_pxa": "Pixa è un unico essere vivente, e PXA e PXP sono il suo <0>corpo</0> — l’<1>Atlas</1>, una sostanza in due fasi. Il PXA è la <2> fase liquida</2>: il mezzo a basse commissioni con cui invii, scambi e regoli, e la forma in cui la coscienza (PXS) si posa. Fai power up e <3> si solidifica</3> 1:1 in PXP; fai power down e <4> torna liquido</4> nell’arco di tredici settimane. Si guadagna dal lavoro che la rete svolge — nessuna azienda lo stampa.",
            "power_up_and_pxa_0_freezes_0": "Fai power up e il PXA <0>si solidifica</0> in PXP, uno a uno, all’istante. Fai power down e il PXP <1>torna liquido</1> in PXA nell’arco di un rilascio di tredici settimane. Stessa sostanza, due fasi: insieme sono l’<2>Atlas</2>, il corpo che sostiene il peso del supra.",
