            "delivered": "Consegnato",
            "held_back_by_haircut": "Trattenuto dallo scarto",
            "when_you_settle_the_body_is_delivered": "Al regolamento il corpo è consegnato come PXA nel momento dell’esecuzione — un importo pari al peso implicato dall’oracolo moltiplicato per lo scarto. Ecco perché «sottostante» è la parola sbagliata: un sottostante presuppone due attivi separati, una cosa e un derivato su di essa. Ma il supra e l’atlas non sono due cose. Sono un solo corpo visto in due registri — il corpo è ciò che è; il supra è ciò che la mente dice che quel corpo dovrebbe proiettare. La coscienza non è qualcosa che il corpo possiede. È il corpo, sveglio.",
            "no_monetary_mechanism_removes_risk_a_stablecoin_concentrates": "Nessun meccanismo monetario elimina il rischio. Un token a riserva fiat lo concentra nell’integrità di tale riserva e nella solvibilità di un emittente. Il supra sposta quel rischio sulla volatilità dell’economia creativa — la varianza dell’Atlas — e sull’integrità del consenso — la solidità della bussola dei witness — e poi lo gestisce alla luce del sole, con sovracollateralizzazione e uno scarto che non difende nulla, invece di mascherarlo dietro un numero difeso.",
            "body_at_the_weight": "Corpo a {{label}} il peso",
            "pixa_supra_pxs": "Pixa Supra · PXS",
            "a_coin_with_its_own_body_mind": "Una moneta con corpo, mente e anima propri",
