            "you_are_about_to_request_a_change": "Stai per richiedere una modifica dell’account di recupero per <0>@{{username}}</0>.",
            "nominate_a_trusted_account_a_co_founder": "Indica un account fidato — un cofondatore, un portafoglio gemello che controlli o un contatto raggiungibile per altre vie — che ti aiuti a riottenere l’accesso se la tua chiave owner venisse persa o compromessa. La procedura di recupero usa lo storico della tua chiave owner, quindi da solo l’account di recupero non può mai impossessarsi del tuo account: può solo aiutarti a recuperarlo. Le modifiche diventano effettive dopo una finestra di attesa di 30 giorni.",
            "strong_30_day_waiting_period_strong_changing": "<strong>Periodo di attesa di 30 giorni.</strong> Cambiare l’account di recupero non è immediato. Una nuova richiesta diventa effettiva <strong>30 giorni dopo la trasmissione</strong>; fino ad allora resta valido l’account attuale. Trasmettere di nuovo durante l’attesa sostituisce la richiesta in sospeso. Reimpostare il valore attuale annulla una modifica in sospeso.",
            "pick_someone_you_trust_personally_a_co": "Scegli una persona di cui ti fidi personalmente: un cofondatore, un account gemello che controlli o un portafoglio il cui titolare puoi contattare per altre vie.",
            "generate_a_fresh_seed_phrase_to_derive": "Genera una nuova frase mnemonica per derivare nuove chiavi per il tuo account. La frase mnemonica è la chiave principale di tutte le chiavi dell’account: conservala al sicuro e non condividerla mai. La chiave owner servirà a firmare la transazione di aggiornamento quando confermerai qui sotto.",
            "this_will_strong_cancel_any_pending_recovery": "Questo <strong>annullerà qualsiasi modifica in sospeso dell’account di recupero</strong> ritrasmettendo lo stesso valore dell’account attuale. La richiesta a 30 giorni verrà sostituita; l’account di recupero attuale resta valido per tutto il tempo.",
            "once_broadcast_the_chain_will_create_a": "Una volta trasmessa, la blockchain creerà una richiesta in sospeso che diventerà effettiva tra <strong>30 giorni</strong>. Il tuo account di recupero attuale (<0>@{{currentRecovery}}</0>) resta valido fino ad allora. Ti verrà chiesta la tua <strong>chiave owner</strong>.",
            "posting_description_1": "Questa chiave va usata per le azioni social, come pubblicare, commentare e votare. Ha un insieme limitato di permessi e non può essere usata per azioni monetarie.",
            "posting_description_2": "Usa questa chiave per accedere ai social network basati su Pixa come Pixagram.com. Conservala al sicuro.",
            "active_description_1": "Questa chiave ha permessi aggiuntivi per azioni monetarie più delicate, come trasferire e scambiare token.",
            "active_description_2": "Quando esegui un'azione relativa al portafoglio, potrebbe esserti chiesto di autenticarti con la chiave Active. Inserisci la tua Active Key solo in app di cui ti fidi, perché chiunque abbia accesso a questa chiave può prendere i tuoi token.",
