            "where_can_i_read_the_full_technical": "Dove posso leggere la specifica tecnica completa?",
            "a_public_ledger_and_a_social_platform": "Un registro pubblico e una piattaforma sociale per la pixel art.",
            "the_liquid_transferable_token_of_the_pixa": "Il token liquido e trasferibile dell’economia Pixa.",
            "the_staked_governance_bearing_form_of_pxa": "La forma di PXA in stake, con diritto di governance.",
            "each_does_something_the_others_cannot": "Ognuno fa qualcosa che gli altri non possono fare.",
            "no_one_pxa_only_emerges_from_protocol": "Nessuno. PXA nasce solo da operazioni del protocollo.",
            "the_genesis_block_once_and_only_once": "Il blocco genesi — una volta, e una sola.",
            "no_one_in_particular_and_everyone_together": "Nessuno in particolare, e tutti insieme.",
            "geometry_not_gravity_no_hand_reaches_in": "Geometria, non gravità. Nessuna mano interviene.",
