            "what_happens_when_the_system_is_stressed": "Che cosa accade quando il sistema è sotto stress.",
            "above_10_000_the_protocol_pauses_new": "Non appena il PXS in circolazione supera il 20 % della capitalizzazione di mercato del PXA, il protocollo interrompe l’emissione di nuovi PXS.",
            "they_cannot_no_minting_key_exists": "Non possono. Non esiste alcuna chiave di conio.",
