            "the_price_feed_for_the_pixasupra_versus": "Il feed dei prezzi di PixaSupra rispetto a Pixa è circa 1:57. Il feed serve a bilanciare gli incentivi tra le valute. PixaSupra e Pixa cercano un equilibrio: dovrebbero esserci <b>3,3 volte più</b> token liquidi che token con riferimento a oracolo, così che PixaSupra resti sotto il 30% della capitalizzazione di Pixa. Significa che oggi abbiamo un margine di <b>3,7x</b> per correggere l’offerta: se il prezzo di Pixa scende di tanto, si applica la regola dell’haircut.",
