            "similar_to_most_stablecoin_its_algorithms_requir": "La correzione di rotta non è la mano di un operatore su una leva: i witness votano per consenso il feed dei prezzi e i parametri del protocollo, e un APR equo permette al sistema di seguire quel feed premiando lo stake di lungo periodo.",
