            "the_author_shall_receive_a_royalty_of": "L’Autore riceverà una royalty del **{{royaltyPercentage}}%** su tutte le vendite o i trasferimenti secondari degli NFT, indipendentemente dal marketplace o dal mezzo di transazione. Tale royalty sarà applicata automaticamente tramite le funzionalità degli smart contract, ove supportate. Qualora la transazione avvenga al di fuori di un sistema automatizzato, il venditore è responsabile di garantire che l’Autore riceva la royalty dovuta e del rispetto dei diritti sopra menzionati.",
